import {conflictCards} from './conflict-view.js';
import {bindChangeHistory} from './change-history-ui.js';
import {bindVersionHistory} from './version-history-ui.js';
import {workspaceAuth,leaveWorkspace,lockWorkspace} from './workspace-auth.js';
export async function bindWorkspaceSync({getState,flush,receive,openDialog,esc,toast,onMember}){
 let status={},busy=false,actionError='',refreshError='',receivedRevision=null;const button=document.querySelector('#workspace-sync'),label=document.querySelector('#workspace-sync-status');
 const {api,renewSession}=await workspaceAuth();const history=bindVersionHistory({flush,receive,openDialog,esc,toast});const changes=bindChangeHistory({api,flush,openDialog,esc,toast});
 function paintNotice(){const notice=document.querySelector('#cloud-notice');if(!notice)return;const message=String(actionError||refreshError||status.lastError||'').trim();notice.textContent=message;notice.hidden=!message;}
 const guard=fn=>async()=>{try{await fn();actionError='';paintNotice();}catch(e){actionError=e.message;toast(e.message);paintNotice();}};
 function paint(){paintNotice();label.textContent=!status.enabled?'尚未启用':!status.signedIn?'请登录':status.paused?'已暂停':status.running?`上传 ${status.progress?.uploaded||0}/${status.progress?.uploadTotal??status.pending??0} · 下载 ${status.progress?.downloaded||0}/${status.progress?.downloadTotal??'待统计'}`:status.lastError?'等待重试':status.conflicts?`${status.conflicts} 项冲突`:status.pending?`待同步 ${status.pending} 项`:!status.lastSyncedAt?'本地就绪':'已同步';const progress=document.querySelector('#cloud-progress');if(progress)progress.textContent=label.textContent;for(const [id,value] of [['cloud-pending',status.pending||0],['cloud-conflict-count',status.conflicts||0]]){const node=document.getElementById(id);if(node)node.textContent=value+' 项';}const conflictButton=document.getElementById('cloud-conflicts');if(conflictButton)conflictButton.hidden=!status.conflicts;label.title=status.lastError||'编辑自动保存在本机；云端每 2 小时同步一次，也可点击立即同步';}
 const cacheRequest=async(action,data)=>{const response=await fetch('/api/cache/'+action,data?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)}:{});const value=await response.json();if(!response.ok)throw Error(value.error||'缓存操作失败');return value;};
 const cachePanel=guard(async()=>{openDialog('清理缓存','<p class="hint">正在统计旧版生成图…</p><p id="cache-message" class="error"></p>');const plan=await cacheRequest('preview');if(!document.querySelector('#dialog')?.open||document.querySelector('#dialog-title')?.textContent!=='清理缓存')return;const size=(plan.bytes/1024**3).toFixed(2);openDialog('清理缓存',`<p>找到 ${plan.count} 张旧版自动生成图，约 ${size} GiB。每套配置最新的生成图会保留，原始图库、配置、历史版本和登录信息不会清理。</p><p>清理后图片会移入 Windows 回收站，可以从回收站找回。</p><p id="cache-message" class="error" hidden></p><div class="actions"><button id="cache-clear" class="primary" ${plan.count?'':'disabled'}>移入回收站</button></div>`);document.querySelector('#cache-clear').onclick=guard(async()=>{const button=document.querySelector('#cache-clear');button.disabled=true;button.textContent='正在移入回收站…';try{const result=await cacheRequest('clear',{signature:plan.signature});openDialog('清理缓存',`<p>已将 ${result.removed} 张旧版生成图移入回收站，约 ${(result.bytes/1024**3).toFixed(2)} GiB。</p>`);}catch(error){button.disabled=false;button.textContent='重新尝试';const message=document.querySelector('#cache-message');message.hidden=false;message.textContent=error.message;throw error;}});});
 async function refresh(){status=await api('status');refreshError='';paint();if(!status.signedIn){try{await renewSession();status=await api('status');}catch{}if(!status.signedIn)await lockWorkspace();status=await api('status');paint();}onMember(status.member);if(status.enabled&&!status.running&&status.workspaceRevision!==receivedRevision){const received=await receive();if(received!==false)receivedRevision=status.workspaceRevision;}}
 async function panel(){actionError='';await refresh();
  const login=`<section class="sync-account"><div><small>当前成员</small><strong>${esc(status.member?.name||'未登录')}</strong></div><div class="actions"><button id="cloud-switch">切换账号</button><button id="cloud-logout">退出登录</button></div></section>`;
  openDialog('多人同步',`${login}<p id="cloud-notice" class="error" role="alert" ${String(status.lastError||'').trim()?'':'hidden'}>${esc(status.lastError||'')}</p><section class="sync-section"><h3>同步状态</h3><div class="sync-stats"><div class="sync-stat"><small>当前状态</small><strong id="cloud-progress">${esc(label.textContent)}</strong></div><div class="sync-stat"><small>待上传</small><strong id="cloud-pending">${status.pending||0} 项</strong></div><div class="sync-stat"><small>待处理冲突</small><strong id="cloud-conflict-count">${status.conflicts||0} 项</strong></div></div><p class="hint">编辑自动保存到本机，云端每 2 小时同步一次。</p><div class="actions">${status.enabled?'<button id="cloud-now" class="primary">立即同步</button><button id="cloud-pause">'+(status.paused?'恢复自动同步':'暂停自动同步')+'</button><button id="cloud-conflicts" '+(status.conflicts?'':'hidden')+'>处理冲突</button>':'<button id="cloud-preview" class="primary">预览并发布本机数据</button><button id="cloud-join">接收已有云端数据</button>'}</div></section><section class="sync-section"><h3>记录与备份</h3><div class="actions"><button id="cloud-history">历史版本</button>${status.changeHistory?'<button id="cloud-changes">修改与提交记录</button>':''}<button id="cloud-backup">下载同步备份</button><button id="cloud-restore" class="primary">还原配置</button></div></section><details class="sync-help"><summary>成员名称与同步说明</summary><p class="hint">当前成员名来自云端工作台成员资料。需要改名时，请由管理员修改成员显示名称，然后退出并重新登录；登录账号保持不变。</p><p class="hint">配置、人工核算价、店铺设置、模板、输出源和机箱图库在成员之间同步。ERP 成本、可销数、生成图和 ZIP 保留在本机。</p><p class="hint">暂停自动同步后仍可立即同步。退出登录不会删除本机数据；切换账号前请完成同步。</p><a href="/cloudbase-maintenance.html" target="_blank">查看维护说明</a></details>`);
  document.querySelector('.sync-help').insertAdjacentHTML('beforebegin','<section class="sync-section"><h3>本机空间</h3><p class="hint">清理旧版自动生成图，保留最新图片和业务数据。</p><div class="actions"><button id="cloud-cache">清理缓存</button></div></section>');
  document.querySelector('#cloud-cache').onclick=cachePanel;
  const leave=guard(async()=>{await flush();for(const id of ['cloud-switch','cloud-logout'])document.getElementById(id).disabled=true;try{await leaveWorkspace();}catch(error){for(const id of ['cloud-switch','cloud-logout'])document.getElementById(id).disabled=false;throw error;}});
  document.querySelector('#cloud-switch').addEventListener('click',leave);
  document.querySelector('#cloud-history').onclick=history.open;document.querySelector('#cloud-restore').onclick=history.restore;document.querySelector('#cloud-changes')?.addEventListener('click',changes.open);
  document.querySelector('#cloud-logout').addEventListener('click',leave);
  document.querySelector('#cloud-now')?.addEventListener('click',guard(async()=>{await renewSession();await flush();await api('run',{});await refresh();toast('已开始同步，可继续编辑');}));
  document.querySelector('#cloud-pause')?.addEventListener('click',guard(async()=>{await api('pause',{paused:!status.paused});await panel();}));
  document.querySelector('#cloud-join')?.addEventListener('click',guard(async()=>{await flush();openDialog('接收云端工作台','<p>当前本机数据会先自动备份，完整下载后切换为云端数据。原始图片会按需下载到本地。</p><button id="cloud-join-confirm" class="primary">备份本机并接收</button>');document.querySelector('#cloud-join-confirm').onclick=guard(async()=>{await api('enable',{mode:'join'});await panel();});}));
  document.querySelector('#cloud-preview')?.addEventListener('click',guard(async()=>{await flush();const p=await api('preview');openDialog('首次同步迁移预览',`<p>配置 ${p.counts.configuration||0} 条，人工核算价 ${p.counts.component||0} 条，输出源 ${p.counts.source||0} 条，模板 ${p.counts.template||0} 条，图库 ${p.counts.gallery||0} 条。</p><p>售价已完成往返换算校验；发布前自动备份本机数据。</p>${p.issues.length?`<p class="error">${p.issues.length} 项待处理</p><pre>${esc(JSON.stringify(p.issues.slice(0,20),null,2))}</pre>`:'<button id="cloud-publish" class="primary">确认发布并启用同步</button>'}`);document.querySelector('#cloud-publish')?.addEventListener('click',guard(async()=>{await api('enable',{mode:'publish',previewHash:p.hash});await panel();}));}));
  document.querySelector('#cloud-conflicts')?.addEventListener('click',guard(async()=>{const {records}=await api('conflicts');openDialog('同步冲突',records.length?conflictCards(records,esc):'<p>没有待处理冲突。</p>');for(const b of document.querySelectorAll('[data-conflict]'))b.onclick=guard(async()=>{await flush();const r=records[Number(b.dataset.conflict)];await api('resolve',{type:r.type,id:r.id,choice:b.dataset.choice});await receive();await panel();});}));
  document.querySelector('#cloud-backup')?.addEventListener('click',guard(async()=>{const b=await api('backup',{}),u=URL.createObjectURL(new Blob([JSON.stringify(b)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download='工作台同步备份_'+b.id+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),10000);}));
 }
 const open=guard(async()=>{await flush();await panel();});
 window.addEventListener('workspace-auth-error',event=>{label.textContent='登录状态需重新验证';label.title=event.detail;toast(event.detail);lockWorkspace().catch(error=>toast(error.message));});
 try{button.onclick=open;await refresh();setInterval(async()=>{if(busy)return;busy=true;try{await refresh();}catch(error){refreshError=error.message;label.textContent='同步状态读取失败';label.title=error.message;paintNotice();}finally{busy=false;}},5000);}catch(e){label.textContent='同步暂不可用';label.title=e.message;}

 return {status:()=>status,open};
}
